import { useEffect, useMemo, useRef, useState } from 'react';
import { SENTENCE_MAX_CHARS, SENTENCE_RUN, drillOrder, seededRng, sentenceReady } from '@lexpad/core';
import { modes as modesApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import type { ApiSentenceFeedback } from '@/api/types.js';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, useBilling } from '@/features/billing/state.js';
import { Speaker } from '@/features/session/cards/Speaker.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useOnline } from '@/lib/useOnline.js';
import { ModeScreen, ModeSummary } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { drillWords } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import styles from '../Modes.module.css';

/**
 * How long a check may take before the screen gives up and offers Try
 * again. A model answer is normally a couple of seconds; this is for a slow
 * one, so nobody stares at "Checking…" for ever.
 */
export const SENTENCE_TIMEOUT_MS = 20_000;

/** Where a check stands. */
type Check =
  | { state: 'idle' }
  | { state: 'checking' }
  | { state: 'done'; feedback: ApiSentenceFeedback }
  | { state: 'offline' }
  | { state: 'resting' }
  | { state: 'locked' }
  | { state: 'failed' };

/**
 * Use it in a sentence (Pro, AI): one of the learner's words, and they write
 * a sentence with it. The server asks a model whether the sentence is
 * natural, awkward, or uses the word in a meaning it does not have, and
 * says why, with a better version when there is one.
 *
 * Practice only (card type sentence, source game): an AI's verdict is not
 * evidence of memory, so no box moves. Needs a connection; the server's
 * allowance is never shown, and when it is used up the check rests until
 * tomorrow. Nothing is counted for a check that failed.
 */
export function UseInSentence({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('sentence');
  const online = useOnline();
  const billing = useBilling((state) => state.state);
  const words = useMemo(
    () =>
      drillOrder(drillWords('sentence', view.words, lang), view.today, seededRng(run.seed)).slice(
        0,
        SENTENCE_RUN,
      ),
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [run.seed],
  );
  const [index, setIndex] = useState(0);
  const [text, setText] = useState('');
  const [check, setCheck] = useState<Check>({ state: 'idle' });
  const pending = useRef<AbortController | undefined>(undefined);
  const shownAt = useRef(0);
  const area = useRef<HTMLTextAreaElement>(null);
  const word = words[index];

  useEffect(() => {
    shownAt.current = Date.now();
    area.current?.focus();
  }, [index, run.seed]);

  // Leaving mid-check abandons the request.
  useEffect(
    () => () => {
      pending.current?.abort();
    },
    [],
  );

  if (word === undefined) {
    return (
      <ModeSummary
        title={t('modes.sentence')}
        lang={lang}
        score={t('modes.scoreOf', {
          right: run.answers.filter((a) => a.correct).length,
          total: run.answers.length,
        })}
        missed={missedWords(run.answers)}
        onAgain={() => {
          run.restart();
          setIndex(0);
          setText('');
          setCheck({ state: 'idle' });
        }}
      />
    );
  }

  const submit = async (): Promise<void> => {
    if (!sentenceReady(text) || check.state === 'checking') return;
    if (!online) {
      setCheck({ state: 'offline' });
      return;
    }
    setCheck({ state: 'checking' });
    const controller = new AbortController();
    pending.current = controller;
    const timer = window.setTimeout(() => {
      controller.abort();
    }, SENTENCE_TIMEOUT_MS);
    try {
      const feedback = await modesApi.judgeSentence(word.id, text.trim(), controller.signal);
      setCheck({ state: 'done', feedback });
      void run.record({
        wordId: word.id,
        headword: word.headword,
        correct: feedback.verdict === 'natural',
        typed: text.trim(),
        latencyMs: Date.now() - shownAt.current,
      });
    } catch (error) {
      if (isApiError(error, 'needsPayment')) setCheck({ state: 'locked' });
      else if (isApiError(error, 'tooMany')) setCheck({ state: 'resting' });
      else if (isApiError(error, 'offline') && !controller.signal.aborted) setCheck({ state: 'offline' });
      else setCheck({ state: 'failed' });
    } finally {
      window.clearTimeout(timer);
      pending.current = undefined;
    }
  };

  const next = (): void => {
    setText('');
    setCheck({ state: 'idle' });
    setIndex(index + 1);
  };

  const done = check.state === 'done';
  const blocked = check.state === 'resting' || check.state === 'locked';
  const message =
    check.state === 'offline' || (!online && !done)
      ? t('modes.offline')
      : check.state === 'resting'
        ? t('modes.resting')
        : check.state === 'failed'
          ? t('modes.failed')
          : check.state === 'locked'
            ? t('modes.lockedSentence')
            : '';

  return (
    <ModeScreen
      title={t('modes.sentence')}
      ask={t('modes.sentenceAsk')}
      counts={false}
      progress={{ done: index, total: words.length }}
      said={
        done
          ? t(`modes.verdict.${check.feedback.verdict}`)
          : check.state === 'checking'
            ? t('modes.sentenceChecking')
            : message
      }
      actions={
        done || blocked ? (
          <button type="button" className={styles.primary} onClick={next}>
            {t('modes.next')}
          </button>
        ) : (
          <button
            type="button"
            className={styles.primary}
            disabled={!sentenceReady(text) || check.state === 'checking' || !online}
            onClick={() => {
              void submit();
            }}
          >
            {check.state === 'checking'
              ? t('modes.sentenceChecking')
              : check.state === 'failed'
                ? t('modes.tryAgain')
                : t('modes.check')}
          </button>
        )
      }
    >
      <div className={styles.prompt}>
        <span className={styles.promptText}>
          <Bilingual lang={lang}>{word.headword}</Bilingual>
        </span>
        <span className={styles.promptSub}>
          <Bilingual lang={meaningLang}>{word.meaning}</Bilingual>
        </span>
      </div>
      <textarea
        ref={area}
        className={styles.textarea}
        value={text}
        lang={lang}
        dir="auto"
        maxLength={SENTENCE_MAX_CHARS}
        aria-label={t('modes.sentenceLabel', { language: LANGUAGE_NAMES[lang] })}
        placeholder={t('modes.sentenceLabel', { language: LANGUAGE_NAMES[lang] })}
        readOnly={done || check.state === 'checking'}
        onChange={(event) => {
          setText(event.target.value);
          if (check.state !== 'checking' && check.state !== 'done') setCheck({ state: 'idle' });
        }}
        onKeyDown={(event) => {
          // Enter checks; Shift+Enter is a new line, as in any message box.
          if (event.key !== 'Enter' || event.shiftKey) return;
          event.preventDefault();
          if (done || blocked) next();
          else void submit();
        }}
      />
      {message !== '' && (
        <p className={cx(styles.note, check.state === 'failed' && styles.noteBad)}>{message}</p>
      )}
      {check.state === 'locked' && offerable(billing, lang, meaningLang) && (
        <ProOffer occasion="sentence" about={{ targetLang: lang, meaningLang }} showPrice={false} />
      )}
      {done && (
        <div className={styles.verdict}>
          <span className={cx(styles.verdictTag, styles[`verdict_${check.feedback.verdict}`])}>
            {t(`modes.verdict.${check.feedback.verdict}`)}
          </span>
          <Bilingual lang={meaningLang} block className={styles.verdictText}>
            {check.feedback.explanation}
          </Bilingual>
          {check.feedback.better !== undefined && check.feedback.better !== '' && (
            <>
              <p className={styles.betterLabel}>{t('modes.better')}</p>
              <div className={styles.better}>
                <Bilingual lang={lang}>{check.feedback.better}</Bilingual>
                <Speaker text={check.feedback.better} lang={lang} variant="back" />
              </div>
            </>
          )}
        </div>
      )}
    </ModeScreen>
  );
}
